"""Head mount trade study (DEC-041): options A-D compared with the project's own calculation modules.
Writes out/head_mount_trade_study.md. All numbers are evidence class `calculated`."""
from __future__ import annotations

import math

from .. import params as P
from . import f, gap, mass_cg, motion, structure, table

ROW = {"A": P.REV_D_ROW_X, "B": P.REV_D_ROW_X, "C": P.ROW_X}
TIP_C = "20 N at front outer corner, cover screwed as shear panel (closed cell)"
TIP_O = "20 N at front outer corner, cover NOT structural (open section)"
STATIC_WC = sum(b for _, b, _ in gap.STATIC)


def option_numbers(opt):
    row = ROW[opt]
    dx = row - P.REV_D_ROW_X
    n = {"row_x": row, "mount_x": P.REV_D_HEAD_MOUNT[0] + dx, "head_x": (138.8 + dx, 265.0 + dx)}
    for tag, build in (("p", "prototype PETG-CF"), ("a", "production 6061")):
        d, s = structure.evaluate(opt, build)
        n.update({f"kp_{tag}": s["k_pitch"], f"kr_{tag}": s["k_roll"], f"f1_{tag}": s["f1"], f"tipc_{tag}": d[TIP_C]["front outer corner"],
                  f"tipo_{tag}": d[TIP_O]["front outer corner"], f"ctr_{tag}": d["20 N at row centre"]["row centre"], f"self_{tag}": d["self weight"]["front outer corner"]})
    s = gap.sensitivities(row)
    n.update(sens_caster_centre=s["row centre"]["caster"], sens_caster_rail=s["rail corner"]["caster"], sens_wheel_rail=s["rail corner"]["wheel"],
             touch3=7 / s["rail corner"]["wheel"], touch5=5 / s["rail corner"]["wheel"])
    for pk in ("12", "9"):
        sub = [c for c in mass_cg.cases(0.0, opt) if c["pack"].startswith(pk) and not c["head"].startswith("none")]
        w = min(sub, key=lambda c: c["fwd_tip_margin_mm"])
        n.update({f"tip_{pk}": w["fwd_tip_margin_mm"], f"cgx_{pk}": w["x"], f"caster_{pk}": w["N_caster"], f"caster_brake_{pk}": w["N_caster_brake_slope"], f"mass_{pk}": max(c["m"] for c in sub)})
    n["corner_r"] = math.hypot(n["head_x"][1], 175.0)
    n["swept_r"] = max(n["corner_r"], 278.0)
    n["length"] = n["head_x"][1] - P.BODY_TAIL_X
    n["corner_speed"] = P.YAW_MAX * n["corner_r"] / 1000
    s0 = P.TOF_SENSORS["tof_look_fwd_left"]["xyz"]
    edge = 260.6 + dx
    dep = P.LOOKAHEAD_FWD_DEPRESSION if opt == "C" else 14.0                         # depression used with each head position
    low = dep + P.TOF_FOV_FULL_DEG / 2
    n.update(look_dep=dep, look_range=s0[2] / math.sin(math.radians(dep)), look_lead=s0[0] + s0[2] / math.tan(math.radians(low)) - n["head_x"][1],
             look_clear=s0[2] - (edge - s0[0]) * math.tan(math.radians(low)) - P.HEAD_TOP_Z)
    n["unsurveyed_behind_row"] = (154.0 + dx) - P.BODY_TAIL_X
    return n


def run():
    N = {o: option_numbers(o) for o in "ABC"}
    lc = gap.LC
    # option D: rollers on the row centre line at the two ends, pivot link at the option-C mount plane
    piv = P.HEAD_MOUNT[0]
    d_edge = 50.0 / (P.REV_D_ROW_X - piv)            # window edge motion per mm of pivot height (row stays on the rollers)
    D = {"sens_caster_edge": d_edge * piv / lc, "sens_wheel_edge": d_edge * 0.5 * (1 + piv / lc), "roller_debris": 1.0,
         "width": 350 + 2 * 18, "tip": [c for c in mass_cg.cases(0.0, "A") if c["pack"].startswith("12") and c["head"].startswith("none")][0]["fwd_tip_margin_mm"]}
    md = ["# Head mount trade study (DEC-041)\n",
          f"Generated by `python -m mechanical.common.calc.run_all` (module `calc/mount_trade.py`, contract {P.CONTRACT_VERSION}). Every number is **calculated** with the same models as `out/mech_calcs.md` "
          "(mount = four bearing lands with one assumed contact stiffness per land, 1500 N/mm printed / 6000 N/mm aluminium, plus beam theory for arms and wings; three-point gap kinematics; rigid-body balance with the 12 Ah baseline pack). "
          "Nothing is measured; the ranking is robust to the assumed contact stiffness because it scales every option equally.\n",
          "Fixed in every option: the head interior (four 80 x 100 windows, 87.5 pitch, film z = 10, stack-up and RR-HEAD-ACQ as in `board_envelopes.yaml`), head top z = 45, body Rev E, track 270, caster at -204.\n",
          "## Options\n",
          "- **A** Rev D single central keyed neck: steel tongue in a socket collar on the head centre line, two bearing lands at y = +-31, captive cross pin; row at x = 204.",
          "- **B** Wide twin-arm receiver: two arms on the head at the lane seams (y = +-87.5) slide into two channels under a chassis front beam, one captive draw latch on the centre line; row stays at x = 204, so the arms bridge 73 mm of free span.",
          f"- **C** As B with the overhang removed: the head moves rearward until its wing returns are 17 mm ahead of the tyres; row at x = {P.ROW_X}, the arms shrink to shoes that are fully inside the channels. The nose loses its lower 'chin' (x > 62, z < 50) and overhangs the head by 36 mm.",
          "- **D** Floor-following head: head carried by its own rollers/skids, joined to the chassis by a pivoting link; evaluated with rollers on the row centre line at both ends of the head (the arrangement that best decouples the gap).\n",
          "## Numbers (calculated)\n"]
    def r(label, fmt, *keys, d="n/a"):
        return [label] + [fmt.format(*(N[o][k] for k in keys)) for o in "ABC"] + [d]
    rows = [
        r("Row centre x / head_mount x (mm)", "{:.1f} / {:.1f}", "row_x", "mount_x", d=f"{P.REV_D_ROW_X:.0f} (or shortened as C) / pivot"),
        r("Mount pitch stiffness, printed / aluminium (N m/rad)", "{:.0f} / {:.0f}", "kp_p", "kp_a", d="pivot (0); gap set by rollers"),
        r("Mount roll stiffness, printed / aluminium (N m/rad)", "{:.0f} / {:.0f}", "kr_p", "kr_a", d="set by rollers"),
        r("20 N at front outer corner, cover as shear panel: printed / aluminium (mm)", "{:.2f} / {:.2f}", "tipc_p", "tipc_a", d="about 0.05 (roller and frame compliance)"),
        r("same, cover not structural: printed / aluminium (mm)", "{:.2f} / {:.2f}", "tipo_p", "tipo_a"),
        r("20 N at row centre: printed / aluminium (mm)", "{:.3f} / {:.3f}", "ctr_p", "ctr_a", d="frame sag between rollers only"),
        r("Self-weight sag at the front outer corner: printed / aluminium (mm)", "{:.2f} / {:.2f}", "self_p", "self_a"),
        r("First mode of the mounted head: printed / aluminium (Hz)", "{:.0f} / {:.0f}", "f1_p", "f1_a", d="head bounce on rollers; link adds a low pitch mode"),
        r("Gap change at the row centre per mm at the caster (mm)", "{:.2f}", "sens_caster_centre", d="0.00 at the row; +-{:.2f} at the window edges".format(D["sens_caster_edge"])),
        r("Gap change at the leading-rail corner per mm at the caster (mm)", "{:.2f}", "sens_caster_rail", d="{:.2f}".format(D["sens_caster_edge"] * 59.2 / 50)),
        r("Gap change at the leading-rail corner per mm single-wheel drop (mm)", "{:.2f}", "sens_wheel_rail", d="{:.2f}; but 1.00 per mm under a roller".format(D["sens_wheel_edge"] * 59.2 / 50)),
        r("Single feature that makes the 3 mm / 5 mm rail touch (mm)", "{:.1f} / {:.1f}", "touch3", "touch5", d="rail concept changes (rollers are the first contact)"),
        r("Forward tip margin, 12 Ah pack, heaviest head, 0.4 m/s2 braking on 5 deg down-slope (mm)", "{:+.1f}", "tip_12", d="{:+.0f} (head weight on its own rollers)".format(D["tip"])),
        r("same with the 9 Ah alternative pack (mm)", "{:+.1f}", "tip_9"),
        r("Static caster load, same worst case, 12 Ah (N)", "{:.1f}", "caster_12", d="about 25"),
        r("Heaviest operating mass, 12 Ah (kg)", "{:.2f}", "mass_12", d="about +0.25 (rollers, link, bearings)"),
        r("Outer head corner radius / swept radius incl. tail (mm)", "{:.0f} / {:.0f}", "corner_r", "swept_r", d="as A or C, + roller width"),
        r("Corner speed at 0.30 rad/s (m/s)", "{:.3f}", "corner_speed"),
        r("Overall length tail to leading rail (mm)", "{:.0f}", "length", d="as A or C"),
        r("Floor behind the row that a forward pass cannot reach from a wall (mm)", "{:.0f}", "unsurveyed_behind_row", d="as A or C"),
        r("Forward look-ahead: depression / centre-ray range / cone clearance over the head edge (deg / mm / mm)", "{:.0f} / {:.0f} / {:.0f}", "look_dep", "look_range", "look_clear", d="as A or C"),
        r("Forward look-ahead: nearest visible floor ahead of the leading rail (mm)", "{:.0f}", "look_lead"),
        ["Overall head width (mm)", "350", "350", "350", f"{D['width']} with 18 mm end rollers, or rollers inside the swath"],
    ]
    md.append(table(["Quantity", "A central neck", "B twin arms, row 204", "C twin shoes, row {:.1f}".format(P.ROW_X), "D floor-following"], rows))
    md.append(f"\nStopping distance at {P.V_MAX_FWD} m/s is {motion.stop(P.V_MAX_FWD) * 1000:.0f} mm for every option; a drop-off must be visible further ahead than that.\n")
    md.append("## Non-numeric criteria\n")
    md.append(table(["Criterion", "A central neck", "B twin arms", "C twin shoes, short overhang", "D floor-following"], [
        ["Head swap with gloves", "Pull a 4.6 mm captive cross pin low under the neck, slide head +x off a 44 mm tongue; pin is small and hidden; keying by tongue chamfers", "One draw-latch lever on the centre line, visible from above; slide +x on two arms 175 mm apart: self-aligning, cannot be fitted skewed", "Same as B; lever sits just ahead of the nose tip above the head cover; 66 mm slide travel; shoes double as carry handles/feet on the bench stand", "Latch plus link pin plus roller guards; head must be lowered onto its rollers while aligning the link: two-handed, more parts to handle with gloves"],
        ["J1/J2 routing (board landings on the seams y = +-87.5)", "Ports at the seams, pigtails cross 90 mm of open space to the nose-top receptacles; neck occupies the centre", "Ports sit directly above the arms; pigtails can be clipped along the arms; 200 mm long", "Ports above the shoes; receptacles on the nose top are 60 mm away -> pigtails about 150 mm, clipped to the shoe roots, no loop near the look-ahead cones", "Pigtails must flex with every floor undulation: flex-rated cable and strain relief needed, cold flex life becomes a test item"],
        ["Contamination transfer / cleanability", "No floor contact ahead of or beside the windows. Neck shroud is a hollow loft with a hidden underside and socket pocket: hard to wipe", "No added floor contact. Two open arms: wipeable, but the open gap between body and head collects debris", "No added floor contact. Channels are open underneath (drain, wipe from below); head rear is 17 mm from the tyres -> tyre spray reaches the rear wall and wing returns: add a wipeable splash lip", "Rollers touch floor that is NOT yet surveyed (beside the swath = the next pass, or ahead in reverse) and carry loose ore dust forward: sample transfer and smearing; rollers, axles and guards are the hardest parts to decontaminate"],
        ["Wall / bulkhead residual strips", "Front 11 mm rail lead + film margin; side 3.75 mm; pivot needs 318 mm", "Same as A", "Front and side unchanged; pivot radius is tail-limited (278 mm): 40 mm closer turns, 73 mm less unreachable floor behind the row", "Side strips grow by the roller width (about 18 mm each side) unless rollers sit inside the swath"],
        ["Cliff / look-ahead sight lines", "Nose pair blocked by the z = 45 head -> cheek pair at 14 deg, 670 mm grazing range", "Same as A", "Head edge is 73 mm closer: 18 deg depression instead of 14, 524 mm range instead of 669, stronger return; front cliff sensors move onto the front beam beside each tyre", "As A or C"],
        ["Printability on a 256 mm bed (prototype)", "Socket collar sits exactly on the y = 0 split of the printed head: the joint is in the primary load path", "Each printed half-head carries its own arm; arms need metal inserts (73 mm free span)", "Each half-head carries its own shoe on its seam rib; y = 0 joint is out of the primary load path; shoes are short blocks, channels print flat", "More small parts (forks, roller mounts, link); printed pivots wear and creep in the cold"],
        ["Production cost / parts", "MJF neck shroud, steel tongue, machined collar, pin, 2 lands: 5 mount parts, one sculpted", "Machined front beam, 2 channels, 2 long arms, latch: 6 prismatic parts", "Front beam (part of the chassis plate), 2 channels, 2 shoes, latch: 5 prismatic parts, no sculpted neck; beam also carries the motor mounts", "All of B/C plus 2-4 sealed rollers, axles, pivots, guards and a new calibration campaign"],
        ["Risks specific to the option", "Tip margin and gap pitch sensitivity are the worst of the rigid options", "Arm bending adds sag; long lever keeps the nose-heavy balance", "SiPM front ends are about 65 mm ahead of the brushed gearmotor cans (EMI: check with head electronics); debris can wedge between tyre and head rear (17 mm gap, add deflector); nose must be re-shaped", "Changes the gap and calibration concept (DEC-020), adds floor contact, wear and roller debris error 1:1"],
    ]))
    a, c = N["A"], N["C"]
    md.append("\n## Evaluation of D\n")
    md.append(f"A floor-following head removes the cantilever from the balance (tip margin {D['tip']:+.0f} mm) and makes the row-centre gap independent of chassis pitch. It does not remove gap error: debris or a seam under a roller moves that end 1:1 "
              f"(rigid option C: {c['sens_wheel_rail']:.2f} mm per mm of single-wheel drop, and only when a wheel meets the feature), the window edges still follow the pivot ({D['sens_caster_edge']:.2f} mm per mm), and the head needs a travel limit and "
              "a lift for reversing and for the 3/5 mm rail trials. Its decisive drawback for this project is radiological: the rollers run on floor before it is counted (in the adjacent pass or in reverse), can pick up and redeposit loose uranium-series dust, "
              "and add the least cleanable hardware next to the windows. It also needs a new calibration concept and widens the head or shadows the outer lanes. **Not recommended now.** Keep it as the fallback if the floor-rig trials "
              "(`out/gap_measurement_method.md`) show that a rigid mount cannot hold the calibrated gap interval on real trailer floors.\n")
    md.append("## Recommendation: option C (implemented in `params.py`, layout and all calculations)\n")
    md.append(f"- **Balance**: forward tip margin {a['tip_12']:+.1f} mm (A) -> **{c['tip_12']:+.1f} mm (C)** with the 12 Ah pack and the heaviest head, static caster load {a['caster_12']:.1f} -> {c['caster_12']:.1f} N; with the 9 Ah pack {a['tip_9']:+.1f} -> {c['tip_9']:+.1f} mm. No ballast in any configuration.")
    md.append(f"- **Stiffness**: mount pitch {a['kp_p']:.0f} -> {c['kp_p']:.0f} N m/rad and roll {a['kr_p']:.0f} -> {c['kr_p']:.0f} N m/rad (printed); 20 N at the front outer corner {a['tipc_p']:.2f} -> **{c['tipc_p']:.2f} mm** printed, {a['tipc_a']:.2f} -> {c['tipc_a']:.2f} mm aluminium; first mode {a['f1_p']:.0f} -> {c['f1_p']:.0f} Hz printed.")
    md.append(f"- **Gap**: pitch sensitivity at the row centre {a['sens_caster_centre']:.2f} -> **{c['sens_caster_centre']:.2f} mm per mm** at the caster; worst rail corner per mm of single-wheel drop {a['sens_wheel_rail']:.2f} -> {c['sens_wheel_rail']:.2f}; the 3 mm rail touches at {a['touch3']:.1f} -> {c['touch3']:.1f} mm features, the 5 mm rail at {a['touch5']:.1f} -> {c['touch5']:.1f} mm.")
    md.append(f"- **Envelope**: overall length {a['length']:.0f} -> {c['length']:.0f} mm; outer head corner radius {a['corner_r']:.0f} -> {c['corner_r']:.0f} mm (the tail, 278 mm, now sets the swept circle); corner speed at the yaw limit {a['corner_speed']:.3f} -> {c['corner_speed']:.3f} m/s.")
    md.append("- **Build**: no sculpted neck; each printed half-head has its own bearing shoe on a seam rib; one visible glove-operable latch; receiver channels bolt to the same front beam as the motor mounts (short load path head -> wheels).")
    md.append("- **B** has the same receiver but keeps the 204 mm overhang: it gains stiffness in roll and loses some in sag through the arms, and leaves balance and gap sensitivity as in A. It is only preferable if the nose may not be changed.")
    md.append("\n### What changes with C\n")
    rcv = P.RECEIVER
    md.append(table(["Item", "Rev D / option A", "Option C"], [
        ["frames.head_mount.xyz_mm", "(138.5, 0, 32)", f"({P.HEAD_MOUNT[0]}, 0, {P.HEAD_MOUNT[2]})"],
        ["frames.optics.row_center_x_mm", "204.0", f"{P.ROW_X}"],
        ["Head envelope x (main body)", "138.8 .. 265.0", f"{P.HEAD_ENV_E['x'][0]} .. {P.HEAD_ENV_E['x'][1]}; two shoes reach back to x = {rcv['shoe_x'][0]} at y = +-{rcv['shoe_y']} (16 wide, z {rcv['shoe_z'][0]}..{rcv['shoe_z'][1]})"],
        ["Head-internal geometry in the head_mount frame", "row at +65.5, film at z -22", "unchanged (rigid shift of -72.8 mm in base_link)"],
        ["RR-HEAD-ACQ origin in base_link", "(156.0, 163.0, 34.5)", f"({P.HEAD_ACQ['origin'][0]}, 163.0, 34.5); board coordinates, holes and zones unchanged"],
        ["Nose", "neck shroud x 67..138", f"neck deleted; lower hull cut back to x = {rcv['chin_cut'][0]} below z = {rcv['chin_cut'][1]}; chassis front beam x {rcv['front_beam'][0]}..{rcv['front_beam'][1]}, |y| <= {rcv['front_beam'][3]}"],
        ["Receiver", "tongue + collar + cross pin", f"two channels x {rcv['channel_x'][0]}..{rcv['channel_x'][1]}, z {rcv['channel_z'][0]}..{rcv['channel_z'][1]}, lands at x {rcv['land_x'][0]} and {rcv['land_x'][1]}; x-stop plane x = {rcv['x_stop']}; draw latch under the nose tip"],
        ["HEAD_DOCK switch", "at the neck", f"{P.HEAD_DOCK_SWITCH} behind the left channel, pressed by the seated shoe tip"],
        ["Front cliff ToF", "(49, +-75, 41) on the nose chine", "(46, +-109.5, 31) on the front beam beside each tyre"],
        ["Forward look-ahead depression", "14 deg", f"{P.LOOKAHEAD_FWD_DEPRESSION:.0f} deg"],
    ]))
    md.append("\nOpen points for the lead and the other owners: (1) contract change CCR-11 (mount datum, row x, head envelope); (2) head electronics to confirm the front ends tolerate the gearmotor cans about 65 mm behind the board rear edge (the aluminium spreader and frame screen them; brushed-motor noise is a test item); "
              "(3) ground clearance under the receiver channels is 12 mm (head rails 7 mm); (4) the yaw-rate limit in the contract is tied to the 318 mm corner radius and can be revisited.")
    P.OUT.mkdir(exist_ok=True)
    (P.OUT / "head_mount_trade_study.md").write_text("\n".join(md) + "\n", encoding="utf-8")
    return N, D
